using NovaHarvest.Core.NPC;using NovaHarvest.Core.Quests;namespace NovaHarvest.Core.Systems;public sealed class QuestManager {readonly Dictionary<string,Quest> _quests=new();readonly NPCManager _npc;readonly ProgressionSystem _progression;public IReadOnlyCollection<Quest> AllQuests=>_quests.Values;public QuestManager(NPCManager npc,ProgressionSystem p){_npc=npc;_progression=p;}public bool Add(Quest q){if(q is null||string.IsNullOrWhiteSpace(q.Id)||_quests.ContainsKey(q.Id))return false;_quests.Add(q.Id,q);return true;}public Quest? Find(string id)=>_quests.TryGetValue(id,out var q)?q:null;public IReadOnlyList<Quest> GetActiveQuests()=>_quests.Values.Where(x=>x.Status==QuestStatus.Active).ToList();public IReadOnlyList<Quest> GetCompletedQuests()=>_quests.Values.Where(x=>x.Status==QuestStatus.Completed).ToList();public bool CompleteQuest(string id){var q=Find(id);if(q is null||!q.Complete())return false;var r=q.Reward;if(r is null)return true;_npc.Find(q.GiverNpcId)?.IncreaseFriendship(r.Friendship);if(!string.IsNullOrWhiteSpace(r.UnlockId))_progression.Unlock(r.UnlockId);return true;}}
